package com.hospital.system.controller; import com.hospital.system.model.Appointment; import com.hospital.system.dto.*; import com.hospital.system.service.AppointmentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/appointments") public class AppointmentController {private final AppointmentService s; public AppointmentController(AppointmentService s){this.s=s;} @GetMapping public Object all(){return s.all();} @GetMapping("/{id}") public Appointment one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Appointment> add(@Valid @RequestBody AppointmentRequest x){return ResponseEntity.status(201).body(s.add(x));} @PutMapping("/{id}/status") public Appointment status(@PathVariable Long id,@Valid @RequestBody StatusRequest x){return s.status(id,x.status);} @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
